import { InsightConfig, InsightRecord } from '../types';

export const findInsightTexts = (
  insights: InsightRecord[],
  insightConfig: InsightConfig,
) => {
  const data = insights?.find(
    (insight) =>
      insight.type === insightConfig?.type &&
      insight.template === insightConfig?.template &&
      insight.scope === insightConfig?.scope &&
      insight.sub_scope === insightConfig?.sub_scope &&
      insight.segmented_control === insightConfig?.segmented_control &&
      insight.timeframe === insightConfig.timeframe &&
      insight.country === insightConfig.country,
  );

  return data?.insight_text.split('\n') ?? [];
};
